/**
 * mapper.ts: converts between database rows and the engine's types.
 *
 * Rows use snake_case columns (week_index), the engine uses camelCase
 * (weekIndex). Writes leave user_id out: the database fills it from the
 * signed-in user. On reads:
 * - null columns become missing fields, never undefined keys.
 * - text columns the database types as plain string (source, feel, kind,
 *   availability days) are narrowed, and an unknown value throws.
 * - jsonb columns (entries, week_before_recovery) are checked for shape.
 * The row types come from src/lib/database.types.ts, generated by the CLI.
 */
import type { Database, Json } from '../lib/database.types'
import type {
  CheckIn,
  CheckInEntry,
  GateState,
  Run,
  WeekAvailability,
  WeekResult,
} from '../engine/types'
import { checkAvailability, checkWeekResult } from './validate'

type Tables = Database['public']['Tables']

export type WeekResultRow = Tables['week_results']['Row']
export type GateStateRow = Tables['gate_state']['Row']
export type AvailabilityRow = Tables['week_availability']['Row']
export type RunRow = Tables['runs']['Row']
export type CheckInRow = Tables['check_ins']['Row']
export type OverrideRow = Tables['overrides']['Row']

const oneOf = <T extends string>(
  name: string,
  value: string,
  allowed: readonly T[],
): T => {
  if (!(allowed as readonly string[]).includes(value)) {
    throw new Error(`storage: unexpected ${name} from the database: ${value}`)
  }
  return value as T
}

export const weekResultToRow = (
  result: WeekResult,
): Omit<WeekResultRow, 'user_id'> => ({
  week_index: result.weekIndex,
  target_miles: result.targetMiles,
  actual_miles: result.actualMiles,
  long_run_miles: result.longRunMiles,
  highest_pain: result.highestPain,
})

export const rowToWeekResult = (row: WeekResultRow): WeekResult => ({
  weekIndex: row.week_index,
  targetMiles: row.target_miles,
  actualMiles: row.actual_miles,
  longRunMiles: row.long_run_miles,
  highestPain: row.highest_pain,
})

export const gateStateToRow = (
  state: GateState,
): Omit<GateStateRow, 'user_id'> => ({
  reduced_mode: state.reducedMode,
  good_weeks_in_row: state.goodWeeksInRow,
  last_long_run_miles: state.lastLongRunMiles,
  week_before_recovery: state.weekBeforeRecovery ?? null,
})

export const rowToGateState = (row: GateStateRow): GateState => {
  const state: GateState = {
    reducedMode: row.reduced_mode,
    goodWeeksInRow: row.good_weeks_in_row,
    lastLongRunMiles: row.last_long_run_miles,
  }
  const saved: Json | null = row.week_before_recovery
  if (saved === null) return state
  if (typeof saved !== 'object' || Array.isArray(saved)) {
    throw new Error('storage: week_before_recovery must be a week result')
  }
  const week = saved as unknown as WeekResult
  checkWeekResult(week)
  return { ...state, weekBeforeRecovery: week }
}

export const availabilityToRow = (
  weekIndex: number,
  days: WeekAvailability,
): Omit<AvailabilityRow, 'user_id'> => ({
  week_index: weekIndex,
  days,
})

export const rowToAvailability = (row: AvailabilityRow): WeekAvailability => {
  const days = row.days as WeekAvailability
  checkAvailability(days)
  return days
}

export const runToRow = (run: Run): Omit<RunRow, 'user_id'> => ({
  id: run.id,
  date: run.date,
  miles: run.miles,
  source: run.source,
})

export const rowToRun = (row: RunRow): Run => ({
  id: row.id,
  date: row.date,
  miles: row.miles,
  source: oneOf('source', row.source, ['strava', 'in_app']),
})

export const checkInToRow = (
  checkIn: CheckIn,
): Omit<CheckInRow, 'user_id'> => ({
  id: checkIn.id,
  date: checkIn.date,
  workout_id: checkIn.workoutId ?? null,
  activity_id: checkIn.activityId ?? null,
  feel: checkIn.feel,
  kind: checkIn.kind,
  note: checkIn.note ?? null,
  entries: checkIn.entries,
})

export const rowToCheckIn = (row: CheckInRow): CheckIn => {
  if (!Array.isArray(row.entries)) {
    throw new Error('storage: check-in entries must be a list')
  }
  return {
    id: row.id,
    date: row.date,
    feel: oneOf('feel', row.feel, ['good', 'okay', 'rough']),
    kind: oneOf('kind', row.kind, ['afterRun', 'nextMorning']),
    entries: row.entries as unknown as CheckInEntry[],
    ...(row.workout_id === null ? {} : { workoutId: row.workout_id }),
    ...(row.activity_id === null ? {} : { activityId: row.activity_id }),
    ...(row.note === null ? {} : { note: row.note }),
  }
}

export const overrideToRow = (
  runId: string,
  workoutId: string,
): Omit<OverrideRow, 'user_id'> => ({
  run_id: runId,
  workout_id: workoutId,
})

export const rowsToOverrides = (rows: OverrideRow[]): Record<string, string> =>
  Object.fromEntries(rows.map((row) => [row.run_id, row.workout_id]))
